```python
import serial
import time

ser = serial.Serial('COM3', 115200)

def send_command(command, arg=None):
    ser.write((command + ' ' + str(arg) + '\n').encode())

def get_gp():
    send_command('gp')
    response = ser.readline().decode().strip()
    return response

def start_tempMonitoring():
    send_command('tm', 1)

def stop_tempMonitoring():
    send_command('tm', 0)

def start_micMonitoring():
    send_command('am', 1)

def stop_micMonitoring():
    send_command('am', 0)

# Example usage
print("System Info:", get_gp())
start_tempMonitoring()
time.sleep(5)
stop_tempMonitoring()
start_micMonitoring()
time.sleep(5)
stop_micMonitoring()

ser.close()
```

