```
#include <metal_stdlib>
using namespace metal;

// Define the compute shader function
void multiplyArray(float4* dst, const float4* src, uint3 gid) {
    // Get the index of the current thread in the grid
    uint index = gid.x + gid.y * src[0].width + gid.z * src[0].width * src[0].height;

    // Multiply the current element in the array by the scalar
    dst[index] = float4(src[index].x * 2.0, src[index].y * 2.0, src[index].z * 2.0, src[index].w * 2.0);
}

int main() {
    // Set up the device and default device queue
    MTLDevice* device = MTLCreateSystemDefaultDevice();
    MTLCommandQueue* queue = device->newCommandQueue();

    // Define the compute shader source code
    std::string source =
        "#version 300\n"
        "\n"
        "kernel void multiplyArray(float4* dst, const float4* src, uint3 gid) {\n"
        "    // Get the index of the current thread in the grid\n"
        "    uint index = gid.x + gid.y * src[0].width + gid.z * src[0].width * src[0].height;\n"
        "\n"
        "    // Multiply the current element in the array by the scalar\n"
        "    dst[index] = float4(src[index].x * 2.0, src[index].y * 2.0, src[index].z * 2.0, src[index].w * 2.0);\n"
        "}\n";

    // Create a compute shader from the source code
    MTLComputeShader* computeShader = device->newComputeShaderWithSource(source);

    // Define the compute shader's entry point
    computeShader->setEntryPoint(kMtlComputeShaderFunctionMultiplyArray);

    // Define the compute shader's arguments
    MTLArgumentBuffer* arguments = device->newArgumentBuffer();
    arguments->addBufferArgument("dst", 0, MTLArgumentBufferUsageWriteOnly);
    arguments->addBufferArgument("src", 1, MTLArgumentBufferUsageReadOnly);
    arguments->addIntegerArgument("gid", 2, MTLArgumentBufferUsageInput);

    // Set the compute shader's arguments on the command queue
    queue->addComputeCommandEncoder([arguments] {
        arguments->setBuffer(device->newBufferWithBytes(sizeof(float4), MTLResourceOptionsNone, "dst"));
        arguments->setBuffer(device->newBufferWithBytes(sizeof(float4), MTLResourceOptionsNone, "src"));
        arguments->setInteger("gid", 0);
    });

    // Dispatch the compute shader to the queue
    queue->addCommandEncoding([computeShader] {
        computeShader->encodeComputeCommandEncoder([computeShader] {
            computeShader->setFunction("multiplyArray");
        });
    });

    // Execute the command encoding on the queue
    queue->dispatchCompute([computeShader] {
        computeShader->setThreadExecutionOrder(kMTLThreadExecutionOrderAuto);
        computeShader->dispatch小组数(1, 1, 1);
    });

    // Cleanup
    computeShader->release();
    arguments->release();
    queue->release();
    device->release();
}
